const authenticated=data=>{S.demoMode=false;localStorage.setItem('studymate-token',data.token);if(data.refreshToken)localStorage.setItem('studymate-refresh-token',data.refreshToken);S.user=data.user;S.manager=data.user.role==='manager';S.admin=data.user.role==='admin';S.role=S.admin?'Admin':S.manager?'Manager':'Student';S.loginMode='student';S.err='';S.q='';S.tab=S.admin||S.manager?'':'home';S.screen=S.admin?'adash':S.manager?'mdash':'home';S.routeStack=[];close();render();if(!S.admin&&!S.manager)startSocket();startPresence();if(S.admin)refreshAdmin('adash');if(S.manager)refreshManager()};
const login=async()=>{const email=$('#em').value.trim();const password=$('#pw').value;if(!email||!password){S.err='Enter your email and password.';return render()}S.authEmail=email;S.busy=true;S.err='';render();try{authenticated(await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})}))}catch(e){S.err=e.message;render()}finally{S.busy=false}};
const resendConfirmation=async()=>{const email=$('#em')?.value.trim()||S.authEmail||'';if(!email){S.err='Enter your email address first.';return render()}S.authEmail=email;S.busy=true;S.err='';render();try{const r=await api('/api/auth/resend-confirmation',{method:'POST',body:JSON.stringify({email})});S.err=r.message||'Confirmation email sent. Check your inbox and spam folder.';render()}catch(e){S.err=e.message;render()}finally{S.busy=false}};
const registerAccount=async()=>{const payload={name:$('#rn').value.trim(),email:$('#re').value.trim(),department:readDept('rd'),batch:$('#rb').value.trim(),institution:$('#ri').value.trim(),password:$('#rp').value};S.registerDraft={name:payload.name,email:payload.email,department:payload.department,batch:payload.batch};S.busy=true;S.err='';render();try{const result=await api('/api/auth/register',{method:'POST',body:JSON.stringify(payload)});if(result.confirmationRequired){S.loginMode='student';S.authEmail=payload.email;S.screen='login';S.err='Account created. Check your email to confirm it, then sign in.';render();return}authenticated(result)}catch(e){S.err=e.message;render()}finally{S.busy=false}};
const restoreSession=async()=>{if(!localStorage.getItem('studymate-token'))return;try{const data=await api('/api/auth/me');authenticated({token:localStorage.getItem('studymate-token'),user:data.user})}catch{localStorage.removeItem('studymate-token');S.user=null;S.err='Your session ended. Please sign in again.';render()}};
const startSocket=()=>{if(chatSocket&&chatSocket.readyState<=1)return;try{const u=new URL(apiBase());u.protocol=u.protocol==='https:'?'wss:':'ws:';u.pathname=u.pathname.replace(/\/$/,'')+'/api/ws';chatSocket=new WebSocket(u);chatSocket.onopen=()=>chatSocket.send(JSON.stringify({type:'auth',token:localStorage.getItem('studymate-token')}));chatSocket.onmessage=e=>{try{const packet=JSON.parse(e.data);if(packet.type==='message'){const m=packet.message;if(S.chatTarget&&((m.fromId===S.user?.id&&m.toId===S.chatTarget.id)||(m.toId===S.user?.id&&m.fromId===S.chatTarget.id))&&!S.messages.some(x=>x.id===m.id)){S.messages.push(m);if(S.screen==='chat')render()}if(S.screen==='msgs')refreshThreads()}}catch{}};chatSocket.onclose=()=>{chatSocket=null}}catch{chatSocket=null}};
const refreshFriends=async()=>{if(!S.user||S.admin)return;if(S.demoMode){const q=(S.q||'').toLowerCase(),dept=S.friendDepartment||'';S.availableUsers=(S.demoUsers||S.availableUsers).filter(u=>(!q||`${u.name} ${u.email||''}`.toLowerCase().includes(q))&&(!dept||u.department===dept));render(1);return}try{const [requests,friends,users]=await Promise.all([api('/api/friends/requests'),api('/api/friends'),api('/api/users?q='+encodeURIComponent(S.q||'')+'&department='+encodeURIComponent(S.friendDepartment||''))]);S.incomingRequests=requests.incoming;S.outgoingRequests=requests.outgoing;S.serverFriends=friends.friends;S.availableUsers=users.users;S.institutionRequired=users.institutionRequired;render(1)}catch(e){toast(e.message)}};
let friendSearchTimer=null;
const searchFriends=value=>{S.q=value;render(1);clearTimeout(friendSearchTimer);friendSearchTimer=setTimeout(refreshFriends,300)};
const sendFriendRequest=async userId=>{if(S.demoMode){const u=(S.demoUsers||S.availableUsers).find(x=>x.id===Number(userId));if(!u||S.user.friendRequestsEnabled===false)return toast('Friend requests are disabled');u.relationship='outgoing';S.availableUsers=(S.demoUsers||S.availableUsers).filter(x=>(!S.q||`${x.name} ${x.email||''}`.toLowerCase().includes(S.q.toLowerCase()))&&(!S.friendDepartment||x.department===S.friendDepartment));S.outgoingRequests.push({id:Date.now(),user:u});S.activity.unshift({action:'friend_request_sent',actorName:S.user.name,targetName:u.name,createdAt:'Just now'});toast('Demo friend request sent');render();return}try{await api('/api/friends/requests',{method:'POST',body:JSON.stringify({userId})});toast('Friend request sent');await refreshFriends()}catch(e){toast(e.message)}};
const answerFriendRequest=async(id,decision)=>{if(S.demoMode){const req=S.incomingRequests.find(x=>x.id===Number(id));if(!req)return;S.incomingRequests=S.incomingRequests.filter(x=>x.id!==Number(id));const person=(S.demoUsers||S.availableUsers).find(x=>x.id===req.user.id);if(decision==='accept'){if(!S.serverFriends.some(x=>x.id===req.user.id))S.serverFriends.push(req.user);if(person)person.relationship='friend';S.availableUsers=(S.demoUsers||S.availableUsers).filter(u=>(!S.q||`${u.name} ${u.email||''}`.toLowerCase().includes(S.q.toLowerCase()))&&(!S.friendDepartment||u.department===S.friendDepartment));S.activity.unshift({action:'friend_request_accepted',actorName:S.user.name,targetName:req.user.name,createdAt:'Just now'})}else if(person)person.relationship='none';S.availableUsers=(S.demoUsers||S.availableUsers).filter(u=>(!S.q||`${u.name} ${u.email||''}`.toLowerCase().includes(S.q.toLowerCase()))&&(!S.friendDepartment||u.department===S.friendDepartment));toast(decision==='accept'?'Demo friend added':'Demo request declined');render();return}try{await api(`/api/friends/requests/${id}/${decision}`,{method:'POST'});toast(decision==='accept'?'Friend added':'Request declined');await refreshFriends()}catch(e){toast(e.message)}};
const refreshThreads=async()=>{if(!S.user||S.admin)return;if(S.demoMode){render();return}try{const [friends,threads]=await Promise.all([api('/api/friends'),api('/api/messages/threads')]);S.serverFriends=friends.friends;S.threads=threads.threads;render()}catch(e){toast(e.message)}};
const openChat=(id,name)=>{S.chatTarget={id:Number(id),name:String(name||'Student')};S.messages=[];go('chat');if(!S.demoMode)startSocket()};
const refreshMessages=async()=>{if(!S.chatTarget)return;if(S.demoMode){render();return}try{const r=await api('/api/messages/'+S.chatTarget.id);S.messages=r.messages;render()}catch(e){toast(e.message);if(e.message.includes('sign in'))logoutNow()}};
const sendMessage=async()=>{const input=$('#mi');const text=input?.value.trim();if(!text||!S.chatTarget)return;input.disabled=true;if(S.demoMode){const message={id:Date.now(),fromId:S.user.id,toId:S.chatTarget.id,text,createdAt:'Just now'};S.messages.push(message);const thread=S.threads.find(x=>x.user.id===S.chatTarget.id);if(thread)thread.lastMessage=text;S.activity.unshift({action:'message_sent',actorName:S.user.name,targetName:S.chatTarget.name,createdAt:'Just now'});render();return}try{const r=await api('/api/messages',{method:'POST',body:JSON.stringify({toUserId:S.chatTarget.id,text})});if(!S.messages.some(m=>m.id===r.message.id))S.messages.push(r.message);S.threads.sort((a,b)=>a.user.id===S.chatTarget.id?-1:b.user.id===S.chatTarget.id?1:0);render()}catch(e){toast(e.message);if(e.message.includes('sign in'))logoutNow()}finally{const field=$('#mi');if(field)field.disabled=false}};
const refreshAdmin=async view=>{if(!S.user||!S.admin||S.demoMode)return;try{if(view==='adash'){const [overview,presence]=await Promise.all([api('/api/admin/overview'),api('/api/admin/presence')]);S.adminOverview=overview;S.liveUsers=presence.users}if(view==='alist')S.adminUsers=(await api('/api/admin/users')).users;if(view==='areports')S.activity=(await api('/api/admin/activity')).events;if(view==='aset'){const r=await api('/api/admin/settings');S.adm.threshold=r.settings.attendanceThreshold;S.adm.wk=r.settings.weeklySummary}const previousScroll=document.querySelector('.body')?.scrollTop||0;render();if(view==='adash'){const body=document.querySelector('.body');if(body)body.scrollTop=previousScroll}}catch(e){toast(e.message)}};
const saveAdminSettings=async()=>{if(S.demoMode){S.adm.threshold=Number($('#threshold')?.value||75);toast('Demo settings saved on this screen');return}try{const r=await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({attendanceThreshold:S.adm.threshold??75,weeklySummary:S.adm.wk??true})});S.adm.threshold=r.settings.attendanceThreshold;toast('Settings saved to database')}catch(e){toast(e.message)}};
const refreshManager=async()=>{if(!S.user||(!S.manager&&!S.admin)||S.demoMode)return;try{const [overview,materials,assignments,quizzes,students,notifications]=await Promise.all([api('/api/manager/overview'),api('/api/manager/materials'),api('/api/manager/assignments'),api('/api/manager/quizzes'),api('/api/manager/progress'),api('/api/study/notifications')]);S.managerOverview=overview;S.managerMaterials=materials.materials;S.managerAssignments=assignments.assignments;S.managerQuizzes=quizzes.quizzes;S.managerStudents=students.students;S.studyNotifications=notifications.notifications;if(['mdash','mmaterials','massignments','mquizzes','mprogress'].includes(S.screen))render()}catch(e){toast(e.message)}};
const refreshStudy=async()=>{if(!S.user||S.manager||S.admin||S.demoMode)return;try{const [materials,assignments,quizzes,notifications]=await Promise.all([api('/api/materials'),api('/api/assignments'),api('/api/quizzes'),api('/api/study/notifications')]);S.studyMaterials=materials.materials;S.studyAssignments=assignments.assignments;S.studyQuizzes=quizzes.quizzes;S.studyNotifications=notifications.notifications;if(['studyMaterials','studyAssignments','studyQuizzes','studyNotify'].includes(S.screen))render()}catch(e){toast(e.message)}};
const addMaterial=()=>modal(`<h3>Publish course material</h3><input id="mt" placeholder="Material title"><input id="mc" value="Data Structures" placeholder="Course"><select id="mr"><option>Lecture notes</option><option>Past question</option><option>Study guide</option><option>Reference</option></select><textarea id="md" rows="3" placeholder="Description"></textarea><button class="btn" onclick="saveMaterial()">Publish material</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveMaterial=async()=>{const data={title:$('#mt').value,course:$('#mc').value,resourceType:$('#mr').value,description:$('#md').value};if(S.demoMode){S.managerMaterials.unshift({...data,resource_type:data.resourceType,created_at:'Just now'});close();toast('Demo material published');render();return}try{await api('/api/manager/materials',{method:'POST',body:JSON.stringify(data)});close();toast('Material published');await refreshManager()}catch(e){toast(e.message)}};
const addAssignment=()=>modal(`<h3>Create assignment</h3><input id="at" placeholder="Assignment title"><input id="ac" value="Data Structures" placeholder="Course"><textarea id="ai" rows="3" placeholder="Instructions"></textarea><input id="ad" type="date"><button class="btn" onclick="saveAssignment()">Publish assignment</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveAssignment=async()=>{const data={title:$('#at').value,course:$('#ac').value,instructions:$('#ai').value,dueDate:$('#ad').value};if(S.demoMode){S.managerAssignments.unshift({...data,id:Date.now(),due_date:data.dueDate,submissions:0});S.studyAssignments.unshift({...data,id:Date.now()});close();toast('Demo assignment published');render();return}try{await api('/api/manager/assignments',{method:'POST',body:JSON.stringify(data)});close();toast('Assignment published');await refreshManager()}catch(e){toast(e.message)}};
const addQuiz=()=>modal(`<h3>Create quiz</h3><input id="qt" placeholder="Quiz title"><input id="qc" value="Data Structures" placeholder="Course"><input id="qp" placeholder="Question"><input id="q0" placeholder="Option 1"><input id="q1" placeholder="Option 2"><input id="q2" placeholder="Option 3 (optional)"><select id="qa"><option value="0">Correct answer: Option 1</option><option value="1">Correct answer: Option 2</option><option value="2">Correct answer: Option 3</option></select><button class="btn" onclick="saveQuiz()">Publish quiz</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveQuiz=async()=>{const options=[$('#q0').value,$('#q1').value,$('#q2').value].filter(Boolean),data={title:$('#qt').value,course:$('#qc').value,questions:[{prompt:$('#qp').value,options,answer:Number($('#qa').value)}]};if(S.demoMode){S.managerQuizzes.unshift({...data,id:Date.now()});S.studyQuizzes.unshift({...data,id:Date.now()});close();toast('Demo quiz published');render();return}try{await api('/api/manager/quizzes',{method:'POST',body:JSON.stringify(data)});close();toast('Quiz published');await refreshManager()}catch(e){toast(e.message)}};
const managerNotification=()=>modal(`<h3>Notify students</h3><input id="ntitle" placeholder="Notification title"><textarea id="nbody" rows="3" placeholder="Announcement"></textarea><button class="btn" onclick="sendStudyNotification()">Send announcement</button><button class="btn o" onclick="close()">Cancel</button>`);
const sendStudyNotification=async()=>{const data={title:$('#ntitle').value,body:$('#nbody').value};if(S.demoMode){S.studyNotifications.unshift({...data,manager:'Demo Manager',createdAt:'Just now'});close();toast('Demo announcement sent');render();return}try{await api('/api/manager/notifications',{method:'POST',body:JSON.stringify(data)});close();toast('Students notified');await refreshManager()}catch(e){toast(e.message)}};
const submitAssignment=id=>modal(`<h3>Submit assignment</h3><small>Your response will be saved to the coursework database.</small><textarea id="submission" rows="7" placeholder="Type or paste your response"></textarea><button class="btn" onclick="saveSubmission(${Number(id)})">Submit work</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveSubmission=async id=>{if(S.demoMode){const a=S.studyAssignments.find(x=>x.id===id);if(a)a.submission=$('#submission').value;close();toast('Demo assignment submitted');render();return}try{await api(`/api/assignments/${id}/submit`,{method:'POST',body:JSON.stringify({response:$('#submission').value})});close();toast('Assignment submitted');await refreshStudy()}catch(e){toast(e.message)}};
const startQuiz=id=>{S.activeQuiz=S.studyQuizzes.find(q=>q.id===id);S.quizAnswers=Array(S.activeQuiz?.questions.length||0).fill(null);render()};
const submitQuiz=async()=>{if(S.quizAnswers.some(a=>a===null))return toast('Answer each question first');if(S.demoMode){const score=S.activeQuiz.questions.reduce((n,q,i)=>n+(q.answer===S.quizAnswers[i]?1:0),0),total=S.activeQuiz.questions.length;S.activeQuiz=null;S.quizAnswers=[];toast(`Demo quiz result: ${score}/${total}`);render();return}try{const r=await api(`/api/quizzes/${S.activeQuiz.id}/attempt`,{method:'POST',body:JSON.stringify({answers:S.quizAnswers})});S.activeQuiz=null;S.quizAnswers=[];toast(`Quiz result: ${r.score}/${r.total}`);await refreshStudy()}catch(e){toast(e.message)}};
const askStudy=question=>{const text=question||$('#aiq')?.value.trim();if(!text)return toast('Type a study question');S.aiQuestion=text;const q=text.toLowerCase();S.aiAnswer=q.includes('quiz')?'Review the course materials, make a short revision list, then take a practice quiz. Check missed answers and revisit those topics.':q.includes('focus')?'Choose one small task, set the 25-minute focus timer, silence distractions and take a short break when it ends.':q.includes('routine')?'Plan short study blocks around your class routine. Start with the nearest deadline and leave a review block before each quiz.':'Break the topic into small parts, review the course notes, practise one example, and add the next study block to your planner. This assistant uses built-in demo guidance.';render()};
const activityLabel=a=>({cr_community_posted:'CR community update posted',cr_access_changed:'CR access changed',assignment_submitted:'Assignment submitted',account_registered:'Student account created',login:'Signed in',logout:'Signed out',friend_request_sent:'Friend request sent',friend_request_accepted:'Friend request accepted',friend_request_rejected:'Friend request declined',message_sent:'Message sent (content hidden)',admin_message_sent:'Admin message sent',admin_seeded:'Admin account initialized'}[a]||a);
const addTaskPrompt=()=>modal(`<h3>Add task</h3><input id="nt" placeholder="Task title"><input id="ns" placeholder="Subject · duration"><button class="btn" onclick="addTask()">Add task</button><button class="btn o" onclick="close()">Cancel</button>`);
const saveProfile=async()=>{const payload={institution:$('#profileInstitution')?.value.trim(),department:readDept('profileDepartment'),batch:$('#profileBatch')?.value.trim(),friendRequestsEnabled:S.user?.friendRequestsEnabled!==false};if(S.demoMode){S.user={...S.user,...payload};toast('Demo profile updated on this device');render();return}try{const r=await api('/api/profile',{method:'PATCH',body:JSON.stringify(payload)});S.user={...S.user,...r.user};toast('Profile saved');render()}catch(e){toast(e.message)}};
const toggleFriendRequests=async()=>{const previous=S.user?.friendRequestsEnabled!==false,next=!previous;S.user.friendRequestsEnabled=next;render();if(S.demoMode){toast(next?'Demo friend requests enabled':'Demo friend requests disabled');return}try{const r=await api('/api/profile',{method:'PATCH',body:JSON.stringify({institution:S.user.institution,department:S.user.department,batch:S.user.batch,friendRequestsEnabled:next})});S.user={...S.user,...r.user};toast(next?'Friend requests enabled':'Friend requests disabled');render()}catch(e){S.user.friendRequestsEnabled=previous;toast(e.message);render()}};
const uploadAvatar=async file=>{if(!file)return;if(file.size>8*1024*1024){toast('Choose an image smaller than 8 MB');return}try{const img=await createImageBitmap(file),canvas=document.createElement('canvas'),size=256;canvas.width=size;canvas.height=size;const side=Math.min(img.width,img.height),sx=(img.width-side)/2,sy=(img.height-side)/2;canvas.getContext('2d').drawImage(img,sx,sy,side,side,0,0,size,size);img.close();const avatarData=canvas.toDataURL('image/jpeg',0.82);if(S.demoMode){S.user={...S.user,avatarData};toast('Demo profile photo updated');render();return}const r=await api('/api/profile/avatar',{method:'PUT',body:JSON.stringify({avatarData})});S.user={...S.user,...r.user};toast('Profile photo saved');render()}catch(e){toast(e.message||'Could not upload this image')}};
const clearAvatar=async()=>{if(S.demoMode){S.user={...S.user,avatarData:null};toast('Demo profile photo removed');render();return}try{const r=await api('/api/profile/avatar',{method:'PUT',body:JSON.stringify({avatarData:null})});S.user={...S.user,...r.user};toast('Profile photo removed');render()}catch(e){toast(e.message)}};
const setPomFromInput=()=>{const value=Number($('#focusMinutes')?.value);if(!Number.isInteger(value)||value<1||value>180)return toast('Choose a duration from 1 to 180 minutes');setPom(value)};
const changeAccountRole=async(userId,role)=>{const label=role==='manager'?'Manager':'Student';if(!confirm(`Change this account to ${label}?`))return;if(S.demoMode){const u=S.adminUsers.find(x=>x.id===Number(userId));if(u){u.role=role;if(role!=='student')u.isCR=false;S.activity.unshift({action:'account_role_changed',actorName:S.user.name,targetName:u.name,createdAt:'Just now'})}toast(`Demo account role changed to ${label}`);render();return}try{await api(`/api/admin/users/${Number(userId)}/role`,{method:'PATCH',body:JSON.stringify({role})});toast(`Account role changed to ${label}`);await refreshAdmin('alist')}catch(e){toast(e.message)}};
const adminMessagePrompt=(userId,name)=>modal(`<h3>Message ${esc(name)}</h3><small>This private StudyMate notice will appear in the recipient's notifications.</small><input id="adminMsgTitle" maxlength="120" placeholder="Message title"><textarea id="adminMsgBody" rows="5" maxlength="1200" placeholder="Write your message"></textarea><button class="btn" onclick="sendAdminMessage(${Number(userId)})">Send message</button><button class="btn o" onclick="close()">Cancel</button>`);
const refreshCrPosts=async()=>{if(S.demoMode){render();return}try{const r=await api('/api/community/cr');S.crPosts=r.messages||[];render()}catch(e){toast(e.message)}};
const composeCrPost=()=>{if(!S.user?.isCR)return toast('Only a designated Class Representative can post');modal(`<h3>Post a class update</h3><small>This will be visible to students in ${esc(S.user.institution||'your institution')}.</small><textarea id="crBody" rows=5 maxlength=1200 placeholder="Class update or announcement"></textarea><button class="btn" onclick="sendCrPost()">Post update</button><button class="btn o" onclick="close()">Cancel</button>`)};
const sendCrPost=async()=>{const body=$('#crBody')?.value.trim();if(!body)return toast('Write an update first');if(!S.user?.isCR)return toast('Only a designated Class Representative can post');if(S.demoMode){S.crPosts.unshift({id:Date.now(),authorName:S.user.name,department:S.user.department,batch:S.user.batch,createdAt:'Just now',body});S.activity.unshift({action:'cr_community_posted',actorName:S.user.name,createdAt:'Just now'});close();toast('Demo class update posted');render();return}try{await api('/api/community/cr',{method:'POST',body:JSON.stringify({body})});close();toast('Class update posted');await refreshCrPosts()}catch(e){toast(e.message)}};
const setCrStatus=async(userId,enabled)=>{const label=enabled?'grant CR access':'remove CR access';if(!confirm(`Are you sure you want to ${label}?`))return;if(S.demoMode){const u=S.adminUsers.find(x=>x.id===Number(userId));if(!u||u.role!=='student')return toast('Only students can be CRs');u.isCR=!!enabled;S.activity.unshift({action:'cr_access_changed',actorName:S.user.name,targetName:u.name,createdAt:'Just now'});toast(enabled?'Demo CR access granted':'Demo CR access removed');render();return}try{const r=await api(`/api/admin/users/${Number(userId)}/cr`,{method:'PATCH',body:JSON.stringify({isCR:!!enabled})});const u=S.adminUsers.find(x=>x.id===Number(userId));if(u)u.isCR=r.user.isCR;toast(enabled?'CR access granted':'CR access removed');render()}catch(e){toast(e.message)}};
const sendAdminMessage=async userId=>{const title=$('#adminMsgTitle')?.value.trim(),body=$('#adminMsgBody')?.value.trim();if(!title||!body)return toast('Enter a title and message');if(S.demoMode){const target=S.adminUsers.find(x=>x.id===Number(userId));S.studyNotifications.unshift({id:Date.now(),title,body,manager:S.user.name,createdAt:'Just now',recipient:target?.name||'Demo student'});if(target)target.sentMessages=(target.sentMessages||0)+1;S.activity.unshift({action:'admin_message_sent',actorName:S.user.name,targetName:target?.name||'Demo student',createdAt:'Just now'});close();toast('Demo notice added to sample notifications');render();return}try{await api(`/api/admin/users/${Number(userId)}/message`,{method:'POST',body:JSON.stringify({title,body})});close();toast('Message sent');refreshAdmin('alist')}catch(e){toast(e.message)}};
const addTask=()=>{const t=$('#nt').value.trim();if(!t)return toast('Enter a title');S.tasks.push({t,s:$('#ns').value||'General'});close();toast('Task added');render()};
const addPost=()=>{const t=$('#np').value.trim();if(!t)return toast('Write something first');S.posts.unshift({n:'Alex Morgan',t,l:0,liked:0,c:[]});close();toast('Posted');render()};
const cmt=(k,i)=>modal(`<h3>Comments</h3>${S[k][i].c.map(c=>`<small>💬 ${c}</small>`).join('')||'<small>No comments yet</small>'}<input id="ci" placeholder="Add a comment"><button class="btn" onclick="S['${k}'][${i}].c.push($('#ci').value||'👍');close();toast('Comment added');render()">Send</button><button class="btn o" onclick="close()">Close</button>`);
const f_acc=n=>{S.friends.req=S.friends.req.filter(x=>x!=n);S.friends.list.push(n);toast('Friend added');render()};
const postNotice=()=>modal(`<h3>Post notice</h3><select><option>CSE 2023 - Section A</option><option>All CSE students</option></select><textarea id="nn" rows=3 placeholder="Notice text"></textarea><button class="btn" onclick="const t=$('#nn').value.trim();if(!t)return toast('Write a notice');S.notices.unshift({t,s:'CR notice · just now',c:[]});close();toast('Notice sent');render()">Send</button><button class="btn o" onclick="close()">Cancel</button>`);
const doUpload=()=>{if(!S.file)return toast('Select a file first');const k=$('#ut').value.startsWith('Past');load(()=>{(k?S.pq:S.files).unshift({t:$('#uc').value+(k?' - Past question':' - New notes'),s:'Uploaded by you · just now'});S.file=0;S.inst=k?'Questions':'Files';toast('Uploaded successfully');S.screen='inst'},900)};
const setPom=x=>{clearInterval(S.pomRun);S.pomRun=null;S.pomMax=S.pom=x*60;render()};
const togglePom=()=>{if(S.pomRun){clearInterval(S.pomRun);S.pomRun=null}else S.pomRun=setInterval(()=>{if(--S.pom<=0){clearInterval(S.pomRun);S.pomRun=null;S.pom=S.pomMax;toast('Session complete! 🎉')}if(S.screen=='pomo')render()},1000);render()};
render();
restoreSession();
